const modelRevision = '3402761519775515d44f7eaa35e39333d55298e5'
const expectedModelBytes = 22_608_133

export const separatorModelUrl = `https://huggingface.co/elicwhite/scnet-browser-onnx/resolve/${modelRevision}/scnet_base_fp16.onnx`
export const approximateModelBytes = 22 * 1024 * 1024
export const approximateRuntimeBytes = 12 * 1024 * 1024
export const separationSampleRate = 44_100 as const
export const aiAssetCacheName = 'transcribe-pwa-ai-assets-v4'
export const ortRuntimeBaseUrl = 'https://cdn.jsdelivr.net/npm/onnxruntime-web@1.24.3/dist/'

const ortRuntimeFiles = [
  'ort-wasm-simd-threaded.mjs',
  'ort-wasm-simd-threaded.wasm',
] as const

const fftSize = 4_096
const hopSize = 1_024
const modelFrames = 476
const modelChunkSize = 485_100
const paddedSampleCount = (modelFrames - 1) * hopSize + fftSize

export interface DownloadProgress {
  loaded: number
  total: number | null
}

export interface DecodedClip {
  left: Float32Array
  right: Float32Array
  duration: number
}

export interface StereoStem {
  left: Float32Array
  right: Float32Array
}

export interface CompactStereoStem {
  left: Int16Array
  right: Int16Array
}

export const stemIds = ['bass', 'drums', 'vocals', 'other'] as const
export type StemId = typeof stemIds[number]
export type SeparationResult = Record<StemId, StereoStem>
export type CompactSeparationResult = Record<StemId, CompactStereoStem>

// Keep four-stem intermediate PCM below the peak of the full Float32 output.
// Headroom is restored when writing the final WAVs.
export const compactStorageScale = 0.25

export function toCompactSample(sample: number): number {
  if (!Number.isFinite(sample)) return 0
  return Math.max(-32_768, Math.min(32_767, Math.round(sample * compactStorageScale * 32_768)))
}

export interface SeparationProgress {
  progress: number
  currentSegment: number
  totalSegments: number
}

function lowPassChannelInPlace(
  channel: Float32Array,
  cutoffHz: number,
  sampleRate = separationSampleRate,
): void {
  // RBJ 2nd-order Butterworth low-pass. This is intentionally gentle: Bass has
  // little useful energy above 8 kHz, while Drums keeps cymbal detail to 14 kHz.
  const omega = 2 * Math.PI * cutoffHz / sampleRate
  const cosine = Math.cos(omega)
  const sine = Math.sin(omega)
  const alpha = sine / (2 * Math.SQRT1_2)
  const a0 = 1 + alpha
  const b0 = ((1 - cosine) / 2) / a0
  const b1 = (1 - cosine) / a0
  const b2 = b0
  const a1 = (-2 * cosine) / a0
  const a2 = (1 - alpha) / a0
  let x1 = 0
  let x2 = 0
  let y1 = 0
  let y2 = 0

  for (let index = 0; index < channel.length; index += 1) {
    const input = Number.isFinite(channel[index]) ? (channel[index] ?? 0) : 0
    const output = b0 * input + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
    channel[index] = output
    x2 = x1
    x1 = input
    y2 = y1
    y1 = output
  }
}

/**
 * Removes the compact mobile model's ultrasonic edge and prevents PCM16 hard
 * clipping. It mutates in place so an iPhone does not need another full set of
 * stem buffers at the end of inference.
 */
export function postProcessSeparationResult(result: SeparationResult): SeparationResult {
  lowPassChannelInPlace(result.bass.left, 8_000)
  lowPassChannelInPlace(result.bass.right, 8_000)
  lowPassChannelInPlace(result.drums.left, 14_000)
  lowPassChannelInPlace(result.drums.right, 14_000)
  lowPassChannelInPlace(result.vocals.left, 16_000)
  lowPassChannelInPlace(result.vocals.right, 16_000)
  lowPassChannelInPlace(result.other.left, 18_000)
  lowPassChannelInPlace(result.other.right, 18_000)

  let peak = 0
  const channels = stemIds.flatMap((id) => [result[id].left, result[id].right])
  for (const channel of channels) {
    for (let index = 0; index < channel.length; index += 1) {
      peak = Math.max(peak, Math.abs(channel[index] ?? 0))
    }
  }
  const scale = peak > 0.98 ? 0.98 / peak : 1
  if (scale < 1) {
    for (const channel of channels) {
      for (let index = 0; index < channel.length; index += 1) {
        channel[index] = (channel[index] ?? 0) * scale
      }
    }
  }
  return result
}

export function resampleDecodedClip(
  clip: DecodedClip,
  sourceSampleRate: number,
  targetSampleRate = separationSampleRate,
): DecodedClip {
  if (sourceSampleRate === targetSampleRate) return clip
  if (!Number.isFinite(sourceSampleRate) || sourceSampleRate <= 0) {
    throw new Error('無法辨識擷取音訊的取樣率。')
  }

  const targetLength = Math.max(1, Math.round(clip.left.length * targetSampleRate / sourceSampleRate))
  const resampleChannel = (source: Float32Array) => {
    const output = new Float32Array(targetLength)
    const scale = sourceSampleRate / targetSampleRate
    for (let index = 0; index < targetLength; index += 1) {
      const position = index * scale
      const lower = Math.min(Math.floor(position), source.length - 1)
      const upper = Math.min(lower + 1, source.length - 1)
      const fraction = position - lower
      output[index] = (source[lower] ?? 0) * (1 - fraction) + (source[upper] ?? 0) * fraction
    }
    return output
  }

  return {
    left: resampleChannel(clip.left),
    right: resampleChannel(clip.right),
    duration: targetLength / targetSampleRate,
  }
}

interface Spectrogram {
  real: Float32Array
  imag: Float32Array
  frequencyBins: number
  frames: number
}

export async function downloadSeparatorModel(
  signal: AbortSignal,
  onProgress: (progress: DownloadProgress) => void,
): Promise<number> {
  const response = await fetch(separatorModelUrl, { signal })
  if (!response.ok) throw new Error(`AI 模型下載失敗（HTTP ${response.status}）。`)

  const header = response.headers.get('content-length')
  const total = header ? Number(header) : null
  let loaded = 0
  if (!response.body) throw new Error('Safari 無法使用串流方式保存 AI 模型。')
  if (!('caches' in globalThis)) throw new Error('這個瀏覽器不能保存 AI 模型。')

  const trackingStream = response.body.pipeThrough(new TransformStream<Uint8Array, Uint8Array>({
    transform(chunk, controller) {
      loaded += chunk.byteLength
      onProgress({ loaded, total })
      controller.enqueue(chunk)
    },
  }))
  const cachedResponse = new Response(trackingStream, {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  })
  const cache = await caches.open(aiAssetCacheName)
  await cache.put(separatorModelUrl, cachedResponse)
  if (loaded !== expectedModelBytes) {
    await cache.delete(separatorModelUrl)
    throw new Error('下載的 AI 模型大小不正確，請刪除後重新下載。')
  }
  return loaded
}

export async function getCachedSeparatorModel(): Promise<Blob | null> {
  if (!('caches' in globalThis)) return null
  const cache = await caches.open(aiAssetCacheName)
  const response = await cache.match(separatorModelUrl)
  return response ? response.blob() : null
}

export async function hasCachedSeparatorModel(): Promise<boolean> {
  if (!('caches' in globalThis)) return false
  const cache = await caches.open(aiAssetCacheName)
  return Boolean(await cache.match(separatorModelUrl))
}

export async function cacheAiRuntime(signal: AbortSignal): Promise<void> {
  if (!('caches' in globalThis)) throw new Error('這個瀏覽器不能保存 AI 執行引擎。')
  const cache = await caches.open(aiAssetCacheName)
  for (const file of ortRuntimeFiles) {
    const url = `${ortRuntimeBaseUrl}${file}`
    const response = await fetch(url, { mode: 'cors', signal })
    if (!response.ok) throw new Error(`AI 執行引擎下載失敗（HTTP ${response.status}）。`)
    await cache.put(url, response)
  }
}

export async function deleteCachedAiAssets(): Promise<void> {
  if ('caches' in globalThis) await caches.delete(aiAssetCacheName)
}

export async function decodeAudioClip(
  blob: Blob,
  startTime: number,
  requestedDuration: number,
): Promise<DecodedClip> {
  const context = new AudioContext({ sampleRate: separationSampleRate })
  try {
    const decoded = await context.decodeAudioData(await blob.arrayBuffer())
    const startFrame = Math.min(
      Math.max(Math.round(startTime * decoded.sampleRate), 0),
      decoded.length,
    )
    const frameCount = Math.min(
      Math.round(requestedDuration * decoded.sampleRate),
      decoded.length - startFrame,
      modelChunkSize,
    )
    if (frameCount <= 0) throw new Error('目前位置已經在歌曲結尾，請把播放位置往前移。')

    const left = decoded.getChannelData(0).slice(startFrame, startFrame + frameCount)
    const rightSource = decoded.numberOfChannels > 1
      ? decoded.getChannelData(1)
      : decoded.getChannelData(0)
    const right = rightSource.slice(startFrame, startFrame + frameCount)
    return { left, right, duration: frameCount / decoded.sampleRate }
  } finally {
    await context.close()
  }
}

// Each model chunk performs thousands of forward/inverse 4,096-point FFTs.
// The butterfly angles depend only on the stage and offset, so computing
// their sine/cosine once per Worker avoids repeating them for every frame.
// Float64 keeps the same precision as the original Math.cos/Math.sin values.
const fftTwiddles = (() => {
  const stages: { cosine: Float64Array; sine: Float64Array }[] = []
  for (let blockSize = 2; blockSize <= fftSize; blockSize *= 2) {
    const half = blockSize / 2
    const angleStep = -2 * Math.PI / blockSize
    const cosine = new Float64Array(half)
    const sine = new Float64Array(half)
    for (let offset = 0; offset < half; offset += 1) {
      const angle = angleStep * offset
      cosine[offset] = Math.cos(angle)
      sine[offset] = Math.sin(angle)
    }
    stages.push({ cosine, sine })
  }
  return stages
})()

function fft(real: Float32Array, imaginary: Float32Array): void {
  const size = real.length
  let reverseIndex = 0
  for (let index = 0; index < size - 1; index += 1) {
    if (index < reverseIndex) {
      const realValue = real[index] ?? 0
      real[index] = real[reverseIndex] ?? 0
      real[reverseIndex] = realValue
      const imaginaryValue = imaginary[index] ?? 0
      imaginary[index] = imaginary[reverseIndex] ?? 0
      imaginary[reverseIndex] = imaginaryValue
    }
    let bit = size >> 1
    while (bit >= 1 && reverseIndex >= bit) {
      reverseIndex -= bit
      bit >>= 1
    }
    reverseIndex += bit
  }

  for (let blockSize = 2, stage = 0; blockSize <= size; blockSize *= 2, stage += 1) {
    const half = blockSize / 2
    const twiddle = fftTwiddles[stage]!
    for (let block = 0; block < size; block += blockSize) {
      for (let offset = 0; offset < half; offset += 1) {
        const cosine = twiddle.cosine[offset]!
        const sine = twiddle.sine[offset]!
        const first = block + offset
        const second = first + half
        const secondReal = real[second] ?? 0
        const secondImaginary = imaginary[second] ?? 0
        const transformedReal = cosine * secondReal - sine * secondImaginary
        const transformedImaginary = cosine * secondImaginary + sine * secondReal
        const firstReal = real[first] ?? 0
        const firstImaginary = imaginary[first] ?? 0
        real[second] = firstReal - transformedReal
        imaginary[second] = firstImaginary - transformedImaginary
        real[first] = firstReal + transformedReal
        imaginary[first] = firstImaginary + transformedImaginary
      }
    }
  }
}

function inverseFft(real: Float32Array, imaginary: Float32Array): void {
  for (let index = 0; index < imaginary.length; index += 1) imaginary[index] = -(imaginary[index] ?? 0)
  fft(real, imaginary)
  for (let index = 0; index < real.length; index += 1) {
    real[index] = (real[index] ?? 0) / real.length
    imaginary[index] = -(imaginary[index] ?? 0) / real.length
  }
}

function stft(signal: Float32Array): Spectrogram {
  const frequencyBins = fftSize / 2 + 1
  const frames = Math.floor((signal.length - fftSize) / hopSize) + 1
  const realPart = new Float32Array(frequencyBins * frames)
  const imaginaryPart = new Float32Array(frequencyBins * frames)
  const scale = 1 / Math.sqrt(fftSize)
  const real = new Float32Array(fftSize)
  const imaginary = new Float32Array(fftSize)

  for (let frame = 0; frame < frames; frame += 1) {
    const sourceOffset = frame * hopSize
    real.fill(0)
    imaginary.fill(0)
    for (let sample = 0; sample < fftSize; sample += 1) real[sample] = signal[sourceOffset + sample] ?? 0
    fft(real, imaginary)
    for (let bin = 0; bin < frequencyBins; bin += 1) {
      realPart[bin * frames + frame] = (real[bin] ?? 0) * scale
      imaginaryPart[bin * frames + frame] = (imaginary[bin] ?? 0) * scale
    }
  }
  return { real: realPart, imag: imaginaryPart, frequencyBins, frames }
}

function inverseStft(
  realPart: Float32Array,
  imaginaryPart: Float32Array,
  frequencyBins: number,
  frames: number,
): Float32Array {
  const outputLength = (frames - 1) * hopSize + fftSize
  const output = new Float32Array(outputLength)
  const windowSum = new Float32Array(outputLength)
  const scale = 1 / Math.sqrt(fftSize)
  const real = new Float32Array(fftSize)
  const imaginary = new Float32Array(fftSize)

  for (let frame = 0; frame < frames; frame += 1) {
    const targetOffset = frame * hopSize
    real.fill(0)
    imaginary.fill(0)
    for (let bin = 0; bin < frequencyBins; bin += 1) {
      real[bin] = realPart[bin * frames + frame] ?? 0
      imaginary[bin] = imaginaryPart[bin * frames + frame] ?? 0
    }
    for (let bin = 1; bin < frequencyBins - 1; bin += 1) {
      real[fftSize - bin] = real[bin] ?? 0
      imaginary[fftSize - bin] = -(imaginary[bin] ?? 0)
    }
    inverseFft(real, imaginary)
    for (let sample = 0; sample < fftSize; sample += 1) {
      const index = targetOffset + sample
      output[index] = (output[index] ?? 0) + (real[sample] ?? 0) * scale * fftSize
      windowSum[index] = (windowSum[index] ?? 0) + 1
    }
  }
  for (let index = 0; index < output.length; index += 1) {
    const divisor = windowSum[index] ?? 0
    if (divisor > 0) output[index] = (output[index] ?? 0) / divisor
  }
  return output
}

export function roundTripStft(signal: Float32Array): Float32Array {
  const spectrum = stft(signal)
  return inverseStft(
    spectrum.real,
    spectrum.imag,
    spectrum.frequencyBins,
    spectrum.frames,
  )
}

function prepareModelInput(clip: DecodedClip): { data: Float32Array; dims: [number, number, number, number] } {
  const leftPadded = new Float32Array(paddedSampleCount)
  const rightPadded = new Float32Array(paddedSampleCount)
  leftPadded.set(clip.left.subarray(0, modelChunkSize))
  rightPadded.set(clip.right.subarray(0, modelChunkSize))
  const left = stft(leftPadded)
  const right = stft(rightPadded)
  const planeSize = left.frequencyBins * left.frames
  const input = new Float32Array(4 * planeSize)
  input.set(left.real, 0)
  input.set(left.imag, planeSize)
  input.set(right.real, 2 * planeSize)
  input.set(right.imag, 3 * planeSize)
  return { data: input, dims: [1, 4, left.frequencyBins, left.frames] }
}

function extractStem(output: Float32Array, sourceIndex: number, targetLength: number): StereoStem {
  const frequencyBins = fftSize / 2 + 1
  const planeSize = frequencyBins * modelFrames
  const base = sourceIndex * 4 * planeSize
  const left = inverseStft(
    output.subarray(base, base + planeSize),
    output.subarray(base + planeSize, base + 2 * planeSize),
    frequencyBins,
    modelFrames,
  )
  const right = inverseStft(
    output.subarray(base + 2 * planeSize, base + 3 * planeSize),
    output.subarray(base + 3 * planeSize, base + 4 * planeSize),
    frequencyBins,
    modelFrames,
  )
  return { left: left.slice(0, targetLength), right: right.slice(0, targetLength) }
}

function extractCompactStem(output: Float32Array, sourceIndex: number, targetLength: number): CompactStereoStem {
  const frequencyBins = fftSize / 2 + 1
  const planeSize = frequencyBins * modelFrames
  const base = sourceIndex * 4 * planeSize
  const leftFloat = inverseStft(
    output.subarray(base, base + planeSize),
    output.subarray(base + planeSize, base + 2 * planeSize),
    frequencyBins,
    modelFrames,
  )
  const rightFloat = inverseStft(
    output.subarray(base + 2 * planeSize, base + 3 * planeSize),
    output.subarray(base + 3 * planeSize, base + 4 * planeSize),
    frequencyBins,
    modelFrames,
  )
  const left = new Int16Array(targetLength)
  const right = new Int16Array(targetLength)
  for (let index = 0; index < targetLength; index += 1) {
    left[index] = toCompactSample(leftFloat[index] ?? 0)
    right[index] = toCompactSample(rightFloat[index] ?? 0)
  }
  return { left, right }
}

export async function separateClip(
  model: Blob,
  clip: DecodedClip,
  onProgress: (progress: number, currentSegment: number, totalSegments: number) => void,
): Promise<SeparationResult> {
  const results = await separateClips(model, [clip], ({ progress, currentSegment, totalSegments }) => {
    onProgress(progress, currentSegment, totalSegments)
  })
  const result = results[0]
  if (!result) throw new Error('SCNet 沒有產生分離結果。')
  return result
}

export async function separateClips(
  model: Blob,
  clips: DecodedClip[],
  onProgress: (progress: SeparationProgress) => void,
): Promise<SeparationResult[]> {
  return runSeparation(model, clips, onProgress, (data, length) => ({
    drums: extractStem(data, 0, length),
    bass: extractStem(data, 1, length),
    other: extractStem(data, 2, length),
    vocals: extractStem(data, 3, length),
  }))
}

export async function separateCompactClips(
  model: Blob,
  clips: DecodedClip[],
  onProgress: (progress: SeparationProgress) => void,
): Promise<CompactSeparationResult[]> {
  return runSeparation(model, clips, onProgress, (data, length) => ({
    drums: extractCompactStem(data, 0, length),
    bass: extractCompactStem(data, 1, length),
    other: extractCompactStem(data, 2, length),
    vocals: extractCompactStem(data, 3, length),
  }))
}

async function runSeparation<T>(
  model: Blob,
  clips: DecodedClip[],
  onProgress: (progress: SeparationProgress) => void,
  extract: (data: Float32Array, length: number) => T,
): Promise<T[]> {
  if (clips.length === 0) return []
  const ort = await import('onnxruntime-web/wasm')
  ort.env.wasm.numThreads = 1
  ort.env.wasm.proxy = false
  ort.env.wasm.wasmPaths = ortRuntimeBaseUrl
  let session: Awaited<ReturnType<typeof ort.InferenceSession.create>> | null = null
  try {
    session = await ort.InferenceSession.create(await model.arrayBuffer(), {
      executionProviders: ['wasm'],
      enableCpuMemArena: false,
      enableMemPattern: false,
      graphOptimizationLevel: 'all',
    })
    const results: T[] = []
    onProgress({ progress: 0.05, currentSegment: 0, totalSegments: clips.length })
    for (let index = 0; index < clips.length; index += 1) {
      const clip = clips[index]
      if (!clip) continue
      let inputTensor: InstanceType<typeof ort.Tensor> | null = null
      let outputTensor: InstanceType<typeof ort.Tensor> | null = null
      try {
        const input = prepareModelInput(clip)
        inputTensor = new ort.Tensor('float32', input.data, input.dims)
        onProgress({
          progress: (index + 0.15) / clips.length,
          currentSegment: index + 1,
          totalSegments: clips.length,
        })
        const inference = await session.run({ spectrogram: inputTensor })
        const candidate = inference.separated
        if (!candidate || !(candidate.data instanceof Float32Array)) {
          throw new Error('SCNet 回傳了無法辨識的音訊資料。')
        }
        outputTensor = candidate
        results.push(extract(candidate.data, clip.left.length))
        onProgress({
          progress: (index + 1) / clips.length,
          currentSegment: index + 1,
          totalSegments: clips.length,
        })
      } finally {
        outputTensor?.dispose()
        inputTensor?.dispose()
      }
    }
    return results
  } finally {
    await session?.release()
  }
}

function mergeStemSegments(segments: StereoStem[], overlapSamples: number): StereoStem {
  if (segments.length === 0) return { left: new Float32Array(), right: new Float32Array() }
  const totalLength = segments.reduce((sum, segment, index) => (
    sum + segment.left.length - (index === 0 ? 0 : Math.min(overlapSamples, segment.left.length))
  ), 0)
  const left = new Float32Array(totalLength)
  const right = new Float32Array(totalLength)
  left.set(segments[0]?.left ?? new Float32Array())
  right.set(segments[0]?.right ?? new Float32Array())
  let written = segments[0]?.left.length ?? 0

  for (let index = 1; index < segments.length; index += 1) {
    const segment = segments[index]
    if (!segment) continue
    const overlap = Math.min(overlapSamples, written, segment.left.length)
    const crossfadeStart = written - overlap
    for (let sample = 0; sample < overlap; sample += 1) {
      const fadeIn = (sample + 1) / (overlap + 1)
      const fadeOut = 1 - fadeIn
      left[crossfadeStart + sample] = (left[crossfadeStart + sample] ?? 0) * fadeOut
        + (segment.left[sample] ?? 0) * fadeIn
      right[crossfadeStart + sample] = (right[crossfadeStart + sample] ?? 0) * fadeOut
        + (segment.right[sample] ?? 0) * fadeIn
    }
    left.set(segment.left.subarray(overlap), written)
    right.set(segment.right.subarray(overlap), written)
    written += segment.left.length - overlap
  }
  return { left, right }
}

export function mergeSeparationSegments(
  segments: SeparationResult[],
  overlapSamples: number,
): SeparationResult {
  return {
    drums: mergeStemSegments(segments.map((segment) => segment.drums), overlapSamples),
    bass: mergeStemSegments(segments.map((segment) => segment.bass), overlapSamples),
    vocals: mergeStemSegments(segments.map((segment) => segment.vocals), overlapSamples),
    other: mergeStemSegments(segments.map((segment) => segment.other), overlapSamples),
  }
}

export function createSeparationAccumulator(totalSamples: number): SeparationResult {
  const createStem = (): StereoStem => ({
    left: new Float32Array(totalSamples),
    right: new Float32Array(totalSamples),
  })
  return { bass: createStem(), drums: createStem(), vocals: createStem(), other: createStem() }
}

/** Merge each Worker result immediately so the phone never retains four copies
 * of every completed segment alongside a second full-length merge buffer. */
export function appendSeparationSegment(
  target: SeparationResult,
  segment: SeparationResult,
  startSample: number,
  overlapSamples: number,
): void {
  for (const id of stemIds) {
    const targetStem = target[id]
    const segmentStem = segment[id]
    const copyLength = Math.min(segmentStem.left.length, targetStem.left.length - startSample)
    if (copyLength <= 0) continue
    const overlap = startSample === 0 ? 0 : Math.min(overlapSamples, copyLength)
    for (const channel of ['left', 'right'] as const) {
      const destination = targetStem[channel]
      const source = segmentStem[channel]
      for (let index = 0; index < overlap; index += 1) {
        const fadeIn = (index + 1) / (overlap + 1)
        destination[startSample + index] = (destination[startSample + index] ?? 0) * (1 - fadeIn)
          + (source[index] ?? 0) * fadeIn
      }
      destination.set(source.subarray(overlap, copyLength), startSample + overlap)
    }
  }
}
